import React from "react";
import styled from "styled-components";
import ellieProfile from "../../images/ellieProfile.jpg";

interface ProfileHeaderProps {
  type: "customer" | "business";
  name: string;
  stat1: number;
  stat2: number;
  stat3: number;
}

const Container = styled.div`
  width: 1200px;
  background: #ffffff;
  border-radius: 16px;
  overflow: hidden;
`;

const HeaderBanner = styled.div`
  height: 140px;
  background-color: #76949F;
  width: 100%;
`;

const Content = styled.div`
  padding: 0 32px 24px;
  display: flex;
  flex-direction: column;
  position: relative;
`;

const ProfileRow = styled.div`
  display: flex;
  align-items: flex-start;
  gap: 16px;
`;

const ProfileImage = styled.img`
  width: 90px;
  height: 90px;
  border-radius: 50%;
  border: 4px solid #fff;
  position: absolute;
  top: -45px;
`;

const TextColumn = styled.div`
  margin-left: 106px; /* aligns left edge with name, not picture */
  margin-top: 12px; /* ensures name sits right below banner */
  display: flex;
  flex-direction: column;
`;

const Name = styled.div`
  font-size: 22px;
  font-weight: 700;
  color: #1a1a1a;
  margin-bottom: 12px;
`;

const StatsRow = styled.div`
  display: flex;
  gap: 60px;
`;

const StatBlock = styled.div`
  display: flex;
  flex-direction: column;
`;

const StatNumber = styled.div`
  font-size: 20px;
  font-weight: 700;
  color: #1a1a1a;
`;

const StatLabel = styled.div`
  font-size: 13px;
  color: #6d6d6d;
  margin-top: 2px;
`;

const ProfileHeader: React.FC<ProfileHeaderProps> = ({
  type,
  name,
  stat1,
  stat2,
  stat3,
}) => {
  return (
    <Container>
      <HeaderBanner />

      <Content>
        <ProfileRow>
          <ProfileImage src={ellieProfile} alt="Profile" />

          <TextColumn>
            <Name>{name}</Name>

            <StatsRow>
              {type === "customer" ? (
                <>
                  <StatBlock>
                    <StatNumber>{stat1}</StatNumber>
                    <StatLabel>Bookings</StatLabel>
                  </StatBlock>
                  <StatBlock>
                    <StatNumber>{stat2}</StatNumber>
                    <StatLabel>Visited</StatLabel>
                  </StatBlock>
                  <StatBlock>
                    <StatNumber>{stat3}</StatNumber>
                    <StatLabel>Active Loyalty Programs</StatLabel>
                  </StatBlock>
                </>
              ) : (
                <>
                  <StatBlock>
                    <StatNumber>{stat1}</StatNumber>
                    <StatLabel>Avg Rating</StatLabel>
                  </StatBlock>
                  <StatBlock>
                    <StatNumber>{stat2}</StatNumber>
                    <StatLabel>Total Clients</StatLabel>
                  </StatBlock>
                  <StatBlock>
                    <StatNumber>{stat3}</StatNumber>
                    <StatLabel>Staff Members</StatLabel>
                  </StatBlock>
                </>
              )}
            </StatsRow>
          </TextColumn>
        </ProfileRow>
      </Content>
    </Container>
  );
};

export default ProfileHeader;
